const NAVCOUNT={people:()=>[EMP.filter(e=>e.f<100).length,"incomplete 201 files"],pulse:()=>[M.rep,"people with repeat lates"],journey:()=>[MDL().journey.upcoming.length,"probation checkpoints in 60 days"],culture:()=>[MDL().culture.anniversaries.length+MDL().culture.birthdays.length,"milestones coming up"],talent:()=>[MDL().talent.open,"open roles"],governance:()=>[MCD.CASES.filter(c=>caseTone(c.status)==="a").length,"open cases"],scoreboard:()=>[EXC.filter(x=>x.sev!=="Routine").length,"high-priority items"]};
const NAVOPEN=(()=>{try{return JSON.parse(localStorage.getItem("mc.navOpen")||"{}")}catch(e){return{}}})();
function navHtml(){const it=(id,n,i,tip)=>`<a href="#${id}" data-id="${id}" data-tipmini="${esc(tip||n)}">${ic(i)}<span class="nl">${n}</span></a>`;
 return`<i class="ind"></i><div class="grp">Start here</div>${it("overview","Dashboard","grid")}${it("office","3D Office","office")}${it("help","How to use","search","How to use this page")}
 <div class="grp">Workspaces</div>${CATS.map(id=>{const w=WS.find(x=>x.id===id),o=!!NAVOPEN[id];return`<div class="ng${o?" open":""}"><a href="#${id}" data-id="${id}" data-tipmini="${CATNO(id)} ${CATNAME[id]}" class="nwi"><span class="nno">${CATNO(id)}</span><span class="nl"><b>${CATNAME[id]}</b><small>${CATSUB[id]}</small></span><em class="nb" data-nb="${id}"></em></a><button class="ntog" type="button" data-ntog="${id}" aria-expanded="${o}" aria-label="Show the sections of ${CATNAME[id]}">${ic("arrow")}</button></div><div class="nsub"${o?"":" hidden"} data-nsub="${id}">${(CAT_SECTIONS[id]||[]).map(s=>`<a href="#${id}:${s.id}" data-sub="${id}:${s.id}"><i class="sd ${s.state}"></i>${esc(s.label)}</a>`).join("")}</div>`}).join("")}
 <div class="grp">Executive views</div>${EXV.map(v=>it("view/"+v.id,v.n,"bars")).join("")}
 <div class="grp">Divisions</div>${it("divisions","All divisions","user")}`}
function paintNav(){CATS.forEach(id=>{const b=document.querySelector(`[data-nb="${id}"]`);if(!b)return;const f=NAVCOUNT[id];if(!f){b.textContent="";b.hidden=true;return}try{const[n,l]=f();b.textContent=n||"";b.hidden=!n;b.title=n+" "+l}catch(e){b.hidden=true}})}
document.addEventListener("click",e=>{const b=e.target.closest&&e.target.closest("[data-ntog]");if(!b)return;e.preventDefault();e.stopPropagation();const id=b.dataset.ntog,sub=document.querySelector(`[data-nsub="${id}"]`),o=sub.hidden;sub.hidden=!o;b.setAttribute("aria-expanded",String(o));b.parentElement.classList.toggle("open",o);NAVOPEN[id]=o;try{localStorage.setItem("mc.navOpen",JSON.stringify(NAVOPEN))}catch(_){}setTimeout(()=>window.ind&&ind(),10)},true);
document.addEventListener("click",e=>{const b=e.target.closest&&e.target.closest("[data-divsel]");if(!b)return;DIVSEL=b.dataset.divsel;const v=$("#view");v.innerHTML=execHtml("division");if(window.enter)enter(v)});
function wsCards(){return sec("c12","Workspaces",`<div class="wsg">${CATS.map(id=>{const f=NAVCOUNT[id],c=f?f():null,L=CAT_SECTIONS[id]||[];return`<button class="wsc" data-go="${id}"><span class="nno">${CATNO(id)}</span><b>${CATNAME[id]}</b><small>${CATSUB[id]}</small><span class="wsm">${L.length} sections${c&&c[0]?` · <em>${c[0]} ${c[1]}</em>`:""}</span></button>`}).join("")}</div><h3 class="sh" style="margin-top:18px">Executive views</h3><div class="chips evc">${EXV.map(v=>`<button data-go="view/${v.id}">${esc(v.n)}</button>`).join("")}</div>`)}

/* ---------- v4.4: workspace pages show every section as a full panel; richer formats; integrated navigation ---------- */
/* Formats: crosstab (rows x columns with heat shading and totals), ranking table, grouped table with subtotals. */
const shade=(v,mx,c)=>v&&mx?`style="background:color-mix(in srgb,${c||"var(--blue)"} ${Math.round(8+v/mx*46)}%,transparent)"`:"";
function crosstab(rows,cols,val,o={}){const M2=rows.map(r=>cols.map(c=>+val(r,c)||0)),rt=M2.map(a=>a.reduce((x,y)=>x+y,0)),ct=cols.map((_,j)=>M2.reduce((x,a)=>x+a[j],0)),mx=Math.max(1,...M2.flat()),fmt=o.fmt||(v=>v||'<span class="mu">·</span>');
 return`<div class="scroll"><table class="xt"${o.label?` aria-label="${esc(o.label)}"`:""}><thead><tr><th scope="col">${esc(o.corner||"")}</th>${cols.map(c=>`<th scope="col">${esc(o.colLabel?o.colLabel(c):c)}</th>`).join("")}${o.noTotal?"":'<th scope="col" class="tot">Total</th>'}</tr></thead><tbody>${rows.map((r,i)=>`<tr${o.rowAttr?o.rowAttr(r):""}><th scope="row">${esc(o.rowLabel?o.rowLabel(r):r)}</th>${M2[i].map(v=>`<td ${shade(v,mx,o.color)}>${fmt(v)}</td>`).join("")}${o.noTotal?"":`<td class="tot">${o.totFmt?o.totFmt(rt[i]):rt[i]}</td>`}</tr>`).join("")}</tbody>${o.noTotal?"":`<tfoot><tr><th scope="row">Total</th>${ct.map(v=>`<td>${o.totFmt?o.totFmt(v):v}</td>`).join("")}<td>${o.totFmt?o.totFmt(ct.reduce((x,y)=>x+y,0)):ct.reduce((x,y)=>x+y,0)}</td></tr></tfoot>`}</table></div>`}
function rankTable(items,o={}){const l=items.filter(x=>x.v!=null).sort((a,b)=>o.asc?a.v-b.v:b.v-a.v).slice(0,o.limit||10),mx=Math.max(1,...l.map(x=>Math.abs(x.v)));if(!l.length)return`<p class="mu">${o.empty||"Nothing to rank yet."}</p>`;
 return`<ol class="rk">${l.map((x,i)=>`<li${x.e!=null?` data-emp="${x.e}" tabindex="0" role="button"`:""}><span class="rkn">${i+1}</span><span class="rkl"><b>${esc(x.label)}</b>${x.sub?`<small>${esc(x.sub)}</small>`:""}</span><span class="rkb"><i style="width:${Math.max(3,Math.abs(x.v)/mx*100)}%"></i></span><b class="rkv">${x.disp!=null?x.disp:x.v}</b></li>`).join("")}</ol>`}
function groupTable(groups,cols,o={}){return`<div class="scroll"><table class="gt"><thead><tr>${cols.map(c=>`<th scope="col">${esc(c)}</th>`).join("")}</tr></thead>${groups.map(g=>`<tbody><tr class="gh"><th colspan="${cols.length-(g.sub?g.sub.length:0)}" scope="rowgroup">${esc(g.name)} <small>${g.rows.length}</small></th>${(g.sub||[]).map(v=>`<td>${v}</td>`).join("")}</tr>${g.rows.map(r=>`<tr${r.e!=null?` data-emp="${r.e}" tabindex="0"`:""}>${r.c.map(v=>`<td>${v}</td>`).join("")}</tr>`).join("")}</tbody>`).join("")}${o.foot?`<tfoot><tr>${o.foot.map(v=>`<td>${v}</td>`).join("")}</tr></tfoot>`:""}</table></div>`}
const divGroups=(rowFn,subFn)=>D.map(([d])=>{const l=EMP.filter(e=>e.dept===d);return{name:d,rows:l.map(e=>({e:e.i,c:rowFn(e)})),sub:subFn?subFn(l):null}});
const pair=(a,b,wa,wb)=>`<div class="pairs"><div style="flex:${wa||1}">${a}</div><div style="flex:${wb||1}">${b}</div></div>`;
const setSec=(cat,id,patch)=>{const s=(CAT_SECTIONS[cat]||[]).find(x=>x.id===id);if(s)Object.assign(s,patch)};
