setSec("people","documents",{html:()=>{const docs=MDL().files201.docs.filter(d=>!d.unavailable);return crosstab(D.map(x=>x[0]),docs.map(d=>d.label),(d,lab)=>{const k=docs.find(x=>x.label===lab).id;return EMP.filter(e=>e.dept===d&&e.files[k]==="on-file").length},{corner:"On file, by division",rowLabel:d=>shortD(d)+" ("+EMP.filter(e=>e.dept===d).length+")",color:"var(--grn)",label:"201 attachments on file by division"})+'<h3 class="sh">Lowest completeness first</h3>'+rankTable(EMP.map(e=>({label:e.name,sub:e.dept,v:e.f,disp:e.f+"%",e:e.i})),{asc:true,limit:12})}});
setSec("people","government",{html:()=>crosstab(D.map(x=>x[0]),["SSS","PhilHealth","Pag-IBIG","TIN"],(d,k)=>EMP.filter(e=>e.dept===d&&e.gov[{SSS:"sss",PhilHealth:"philhealth","Pag-IBIG":"pagibig",TIN:"tin"}[k]]).length,{corner:"Numbers recorded",rowLabel:d=>shortD(d)+" ("+EMP.filter(e=>e.dept===d).length+")",color:"var(--grn)"})+'<h3 class="sh">Per employee</h3>'+peopleTable(EMP,[["Employee",e=>nm(e)[0]],["SSS",e=>sens(esc(e.gov.sss||"—"))],["PhilHealth",e=>sens(esc(e.gov.philhealth||"—"))],["Pag-IBIG",e=>sens(esc(e.gov.pagibig||"—"))],["TIN",e=>sens(esc(e.gov.tin||"—"))]])});
setSec("people","exits",{html:()=>{const x=MDL().exits||[];const by={};x.forEach(p=>{by[p.div]=by[p.div]||{};by[p.div][p.status]=(by[p.div][p.status]||0)+1});const sts=[...new Set(x.map(p=>p.status))];return(x.length?crosstab(Object.keys(by),sts,(d,s)=>by[d][s]||0,{corner:"Division × exit type",color:"var(--pink)"}):"")+exitsHtml()}});
/* Pay & Benefits */
setSec("pay","salary",{html:()=>{const bandOf=v=>v==null?"Not recorded":v<20000?"Under ₱20K":v<30000?"₱20K–30K":v<50000?"₱30K–50K":v<80000?"₱50K–80K":"₱80K+",bands=["Under ₱20K","₱20K–30K","₱30K–50K","₱50K–80K","₱80K+","Not recorded"];
 return pair(crosstab(D.map(x=>x[0]),bands.filter(b=>EMP.some(e=>bandOf(salaryOf(e))===b)),(d,b)=>EMP.filter(e=>e.dept===d&&bandOf(salaryOf(e))===b).length,{corner:"Division × salary band",rowLabel:shortD}),rankTable(D.map(([d])=>{const p=EMP.filter(e=>e.dept===d&&salaryOf(e)!=null);return{label:d,sub:p.length+" with salary",v:p.length?p.reduce((a,e)=>a+salaryOf(e),0)/p.length:null,disp:sens(pesoK(p.length?p.reduce((a,e)=>a+salaryOf(e),0)/p.length:null))}}),{empty:"No salaries recorded."}),3,2)
 +'<h3 class="sh">Salary masterlist, grouped by division with monthly subtotals</h3>'+groupTable(divGroups(e=>[nm(e)[0],esc(e.comp.ptype||"—"),sens(peso(salaryOf(e))),sens(peso(e.comp.allowance)),sens(peso(e.comp.gross))],l=>[sens(peso(l.reduce((a,e)=>a+(salaryOf(e)||0),0))),sens(peso(l.reduce((a,e)=>a+(e.comp.allowance||0),0))),sens(peso(l.reduce((a,e)=>a+(e.comp.gross||0),0)))]),["Employee","Payroll type","Basic salary","Allowance","Gross pay"],{foot:["<b>Company total</b>","",sens(peso(EMP.reduce((a,e)=>a+(salaryOf(e)||0),0))),sens(peso(EMP.reduce((a,e)=>a+(e.comp.allowance||0),0))),sens(peso(EMP.reduce((a,e)=>a+(e.comp.gross||0),0)))]})}});
setSec("pay","hmo",{html:()=>crosstab(D.map(x=>x[0]),["Eligible (Regular)","Not yet eligible"],(d,k)=>EMP.filter(e=>e.dept===d&&(k[0]==="E"?e.status==="Regular":e.status!=="Regular")).length,{corner:"HMO eligibility by status",rowLabel:shortD,color:"var(--grn)"})+'<p class="note" style="margin-top:10px">Eligibility follows regular status. Enrollment, dependents and renewal have no table yet.</p>'});
