/* Workforce Pulse */
setSec("pulse","monthly",{w:"c7"});setSec("pulse","att-reports",{w:"c5",html:()=>donut(Object.entries(MDL().attendance.byType30).sort((a,b)=>b[1]-a[1]).slice(0,7),"Entry types, 30 days","entries")});
