setSec("journey","level-gates",{html:()=>crosstab(D.map(x=>x[0]),["Level 1","Level 2","Level 3"],(d,l)=>EMP.filter(e=>e.dept===d&&("Level "+(e.head?1:e.lvl))===l).length,{corner:"Division × level",rowLabel:shortD})+'<p class="note" style="margin-top:10px">Levels are read from position titles. Target levels, prerequisites and assessors have no table yet.</p>'});
